import java.io.File
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

// Run off the UI thread. Pass only SDK log directories, never the app root.
fun archiveSdkLogs(directories: List<File>, cacheDirectory: File,
    maxBytes: Long = 50L * 1024 * 1024): File {
    require(maxBytes > 0 && directories.isNotEmpty())
    require(directories.all { it.isDirectory }) { "SDK log directory missing" }
    cacheDirectory.mkdirs()
    val output = File.createTempFile("sdk-logs-", ".zip", cacheDirectory)
    var total = 0L
    var entries = 0
    try {
        ZipOutputStream(output.outputStream().buffered()).use { zip ->
            directories.forEachIndexed { index, directory ->
                val root = directory.canonicalFile
                root.walkTopDown().onEnter { dir ->
                    dir.canonicalFile == dir.absoluteFile
                }.filter { it.isFile }.forEach { file ->
                    require(file.canonicalFile == file.absoluteFile) { "Symlink in SDK logs" }
                    val name = file.relativeTo(root).invariantSeparatorsPath
                    zip.putNextEntry(ZipEntry("logs-$index/$name"))
                    file.inputStream().use { input ->
                        val buffer = ByteArray(8192)
                        while (true) {
                            val size = input.read(buffer)
                            if (size < 0) break
                            total += size
                            require(total <= maxBytes) { "SDK log export exceeds size limit" }
                            zip.write(buffer, 0, size)
                        }
                    }
                    zip.closeEntry()
                    entries++
                }
            }
        }
        require(entries > 0 && total > 0) { "No SDK log contents" }
        return output
    } catch (error: Exception) {
        output.delete()
        throw error
    }
}
// Share via FileProvider using content URI + FLAG_GRANT_READ_URI_PERMISSION.
// Keep SDK logs encrypted; export is not decryption.

