import Foundation

// Run off the UI thread. logsURL is only the verified SDK logs directory.
func archiveSdkLogs(logsURL: URL) throws -> URL {
    let manager = FileManager.default
    var isDirectory: ObjCBool = false
    guard manager.fileExists(atPath: logsURL.path, isDirectory: &isDirectory),
          isDirectory.boolValue,
          !(try manager.contentsOfDirectory(atPath: logsURL.path)).isEmpty else {
        throw NSError(domain: "SDKLogs", code: 1,
            userInfo: [NSLocalizedDescriptionKey: "SDK logs missing or empty"])
    }
    let output = manager.temporaryDirectory
        .appendingPathComponent("sdk-logs-\(UUID().uuidString).zip")
    var coordinationError: NSError?
    var copyError: Error?
    NSFileCoordinator().coordinate(readingItemAt: logsURL, options: .forUploading,
        error: &coordinationError) { archive in
        do { try manager.copyItem(at: archive, to: output) }
        catch { copyError = error }
    }
    do {
        if let error = coordinationError { throw error }
        if let error = copyError { throw error }
        let size = try output.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 0
        guard size > 0 else { throw NSError(domain: "SDKLogs", code: 2) }
        return output
    } catch {
        try? manager.removeItem(at: output)
        throw error
    }
}
// Present UIActivityViewController with the returned URL on the main thread.
